    """Convert a Roman numeral to an integer.
    Supports standard symbols I,V,X,L,C,D,M with subtractive notation.
    """
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for ch in reversed(s):
        value = roman_map[ch]
        if value < prev_value:
            total -= value
        else:
            total += value
            prev_value = value
    return total
