{"task_id": "T04", "code": "def solve(s=None):
    """Return True if brackets in s are balanced.
    If called without argument, reads the entire stdin as the input string.
    """
    import sys
    if s is None:
        s = sys.stdin.read()
    # Use a stack for opening brackets
    opening = {'(': ')', '[': ']', '{': '}'}
    closing = {')', ']', '}'}
    stack = []
    for ch in s:
        if ch in opening:
            stack.append(opening[ch])
        elif ch in closing:
            if not stack or stack[-1] != ch:
                return False
            stack.pop()
        # ignore other characters
    return not stack
