def solve(nums=None):
    """Return length of longest strictly increasing subsequence.
    If called without argument, reads a Python literal list from stdin.
    """
    import sys, ast
    if nums is None:
        data = sys.stdin.read().strip()
        if not data:
            nums = []
        else:
            nums = ast.literal_eval(data)
    # Edge case
    if not nums:
        return 0
    # patience sorting tails
    import bisect
    tails = []
    for x in nums:
        # find insertion point for x in tails (first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

