    """Return length of longest strictly increasing subsequence.
    If called without argument, reads a list of integers from stdin.
    The input may be a Python literal (e.g., "[1, 2, 3]") or whitespace-separated numbers.
    """
    import sys, ast, bisect
    if nums is None:
        data = sys.stdin.read().strip()
        if not data:
            nums = []
        else:
            try:
                nums = ast.literal_eval(data)
                # Ensure it's a list of ints
                if not isinstance(nums, (list, tuple)):
                    raise ValueError
                nums = list(nums)
            except Exception:
                # Fallback: split on whitespace
                nums = [int(x) for x in data.split()]
    # Edge case: empty list
    if not nums:
        return 0
    tails = []
    for x in nums:
        # Find position to replace (first element >= x) for strictly increasing
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
