def solve(grid=None):
    """Count islands (connected components of 1s) in a 2D grid.
    If called without argument, reads a Python literal from stdin.
    Returns an integer count.
    """
    import sys, ast
    if grid is None:
        data = sys.stdin.read().strip()
        if not data:
            return 0
        try:
            grid = ast.literal_eval(data)
        except Exception:
            # Fallback: empty grid
            grid = []
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < rows and 0 <= nj < cols and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                dfs(i, j)
    return count

