    """Evaluate Reverse Polish Notation expression with truncating division toward zero.
    Uses integer arithmetic without floating point to avoid precision issues.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # Perform integer division without float
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                # Compute absolute division and apply sign
                sign = -1 if (a * b) < 0 else 1
                res = abs(a) // abs(b)
                stack.append(sign * res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

