def solve(tokens=None):
    """Evaluate Reverse Polish Notation with integer arithmetic.
    Division truncates toward zero.
    """
    import sys, ast
    if tokens is None:
        data = sys.stdin.read().strip()
        if not data:
            return 0
        try:
            tokens = ast.literal_eval(data)
            if isinstance(tokens, str):
                tokens = [tokens]
        except Exception:
            tokens = data.split()
    if isinstance(tokens, str):
        tokens = tokens.split()
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:
                # Truncate toward zero without floating point
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                sign = -1 if (a < 0) ^ (b < 0) else 1
                res = sign * (abs(a) // abs(b))
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

