def solve(grid):
    """Count islands in a binary grid with possibly irregular row lengths.
    Cells with value 1 are connected orthogonally.
    """
    if not grid:
        return 0
    visited = set()
    rows = len(grid)
    def is_land(r, c):
        return 0 <= r < rows and 0 <= c < len(grid[r]) and grid[r][c] == 1
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if not is_land(i, j):
                continue
            visited.add((i, j))
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if is_land(i, j) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

