def solve(tokens=None):
    """Evaluate RPN expression with +, -, *, / (trunc toward zero).
    Accepts list of token strings or reads from stdin.
    """
    import sys, ast
    if tokens is None:
        data = sys.stdin.read().strip()
        if not data:
            return 0
        try:
            tokens = ast.literal_eval(data)
            if isinstance(tokens, str):
                tokens = [tokens]
        except Exception:
            tokens = data.split()
    if isinstance(tokens, str):
        tokens = tokens.split()
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:
                # trunc toward zero division
                if b == 0:
                    raise ZeroDivisionError
                sign = -1 if (a < 0) ^ (b < 0) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

