            if x<0 or x>=n or y<0 or y>=m:
                continue
            if visited[x][y] or grid[x][y]==0:
                continue
            visited[x][y] = True
            stack.extend([(x-1,y),(x+1,y),(x,y-1),(x,y+1)])
    count=0
    for i in range(n):
        for j in range(m):
            if not visited[i][j] and grid[i][j]==1:
                dfs(i,j)
                count+=1
    return count

